from dataclasses import dataclass
from io import BytesIO
from unittest import mock
from functools import wraps
from urllib3.response import HTTPResponse
from urllib3.exceptions import ProtocolError
from urllib3.connectionpool import HTTPConnectionPool
from http.client import responses as http_reasons


@dataclass
class Request:
    """Represents an HTTP request made by urllib3"""
    method: str
    url: str
    body: bytes
    headers: dict
    scheme: str
    host: str
    port: int

@dataclass
class Call:
    """Represents a call made to the mock urllib3"""
    request: Request
    response: object


class MockUrllib3:
    """A mock for urllib3's HTTPConnectionPool to simulate HTTP requests and responses"""
    def __init__(self):
        self._responses = []
        self._calls = []
        self._patcher = None

    def __enter__(self):
        """Start the mock context manager."""
        self.start()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Stop the mock context manager."""
        self.stop()
        self.reset()

    def start(self):
        """Start the mock by patching urllib3's HTTPConnectionPool.urlopen method."""
        def dispatcher(pool, method, url, body=None, headers=None, **kwargs):
            """Dispatches the call to the mock URL open method."""
            return self._mock_urlopen(pool, method, url, body, headers, **kwargs)

        self._patcher = mock.patch.object(
            HTTPConnectionPool,
            "urlopen",
            new=dispatcher
        )
        self._patcher.start()

    def stop(self):
        """Stop the mock by unpatching urllib3's HTTPConnectionPool.urlopen method."""
        if self._patcher:
            self._patcher.stop()
            self._patcher = None

    def reset(self):
        """Reset the mock by clearing the responses and calls."""
        self._responses.clear()

    def activate(self, func):
        """
        Decorator to activate the mock for a specific function.
        This will ensure that the mock is started before the function runs.
        The mock will be stopped after the function completes, regardless of success or failure.

        Usage:

        .. code-block:: python

            from taf.internal.urllib3_mock import MockUrllib3
            responses = MockUrllib3()

            @responses.activate
            def my_test_function():
                # Your test code that uses urllib3
                pass
        """
        @wraps(func)
        def wrapper(*args, **kwargs):
            with self:
                return func(*args, **kwargs)

        return wrapper

    def add(self, method, url, body="", status=200, content_type="application/json", match_querystring=False,
            headers=None):
        """
        Add a mock response for a specific HTTP method and URL.

        :param method: HTTP method (e.g., 'GET', 'POST')
        :param url: URL to mock
        :param body: Response body as a string or bytes
        :param status: HTTP status code (default is 200)
        :param content_type: Content type of the response (default is 'application/json')
        :param match_querystring: Match querystring parameters (default is False)
        :param headers: (optional) Additional headers to include in the response (default is None)
        """
        if isinstance(body, str):
            body = body.encode('utf-8')

        if headers is None:
            response_headers = {"Content-Type": content_type}
        else:
            response_headers = headers
            response_headers.update({"Content-Type": content_type})

        self._responses.append(
            {
                "method": method,
                "url": url,
                "body": body,
                "status": status,
                "content_type": content_type,
                "match_querystring": match_querystring,
                "headers": response_headers
            }
        )

    def add_callback(self, method, url, callback, content_type="application/json"):
        """
        Add a mock response with a callback for a specific HTTP method and URL.

        :param method: HTTP method (e.g., 'GET', 'POST')
        :param url: URL to mock
        :param callback: A function that takes a Request object and returns a tuple (status, headers, body)
        :param content_type: Content type of the response (default is 'application/json')
        """
        self._responses.append(
            {
                "method": method,
                "url": url,
                "callback": callback,
                "content_type": content_type,
                "headers": {"Content-Type": content_type}
            }
        )

    def _find_mock_entry(self, method, url):
        """
        Find a mock entry based on the HTTP method and URL

        :param method: HTTP method (e.g., 'GET', 'POST')
        :param url: URL to match

        :return: The mock entry if found, otherwise None
        """
        for mock_entry in self._responses:
            if method != mock_entry['method']:
                continue

            if mock_entry.get('match_querystring', False):
                if url == mock_entry['url']:
                    return mock_entry
            else:
                if url.partition('?')[0] == mock_entry['url'].partition('?')[0]:
                    return mock_entry

        return None

    def _mock_urlopen(self, pool, method, url, body=None, headers=None, **kwargs):
        """
        Mock implementation of the HTTPConnectionPool.urlopen method.
        This method simulates the behavior of urllib3's urlopen method by returning
        a mock response based on the predefined responses.

        :param pool: The HTTPConnectionPool instance
        :param method: HTTP method (e.g., 'GET', 'POST')
        :param url: URL to mock
        :param body: Request body (default is None)
        :param headers: Request headers (default is None)
        :param kwargs: Additional keyword arguments (not used in this mock)

        :return: An HTTPResponse object or raises an error if no mock entry is found
        """
        request = Request(method, url, body, headers, pool.scheme, pool.host, pool.port)
        mock_entry = self._find_mock_entry(method=method, url=url)

        if not mock_entry:
            error = ProtocolError(f"Connection refused: {method} {url}")
            self._calls.append(Call(request, error))
            raise error

        if 'callback' in mock_entry:
            status, resp_headers, body = mock_entry['callback'](request)
            if isinstance(body, str):
                body = body.encode('utf-8')
        else:
            status = mock_entry['status']
            body = mock_entry['body']
            resp_headers = mock_entry['headers']

        if isinstance(body, Exception):
            self._calls.append(Call(request, body))
            raise body

        reason = http_reasons.get(status, '')
        headers = {'Content-Type': mock_entry['content_type'], **resp_headers}

        response = HTTPResponse(
            status=status,
            reason=reason,
            body=BytesIO(body),
            headers=headers,
            preload_content=False
        )

        self._calls.append(Call(request, response))
        return response
